--------------------------------------------------------------------------------
-- qnice_host_stub.vhd -- SIZE-MEASUREMENT STUB for the Linux-shell build (a1200-lxshell), own code,
-- GENERATED by ext/aexp9_lxshell/tools/mk_qnice_host_stub.py from the QNICE SoC's port list (it replaces
-- QNICE_SOC inside qnice_wrapper; the wrapper's device decoders stay).
-- NOT a working design: it stands in for the host master (rk_bridge driving QNICE's registers and its
-- device bus) so that the bitstream size without the local QNICE SoC can be measured honestly:
-- every output is a distinct register of one long shift chain fed from a real pin (uart_rxd_i), and
-- every input is folded into the chain's feedback, so nothing behind these ports (the core's device
-- bus, the OSD, the settings bits, the memory port) can be trimmed as constant.  Exception: the SD
-- card buses and the console UART are tied idle and the key scan input is not used -- the host build
-- reads its files on Linux and handles the menu key there.
--------------------------------------------------------------------------------
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity qnice_host_stub is
port (
   clk50_i                   : in    std_logic;
   reset_n_i                 : in    std_logic;
   uart_rxd_i                : in    std_logic;
   uart_txd_o                : out   std_logic;
   sd_reset_o                : out   std_logic;
   sd_clk_o                  : out   std_logic;
   sd_mosi_o                 : out   std_logic;
   sd_miso_i                 : in    std_logic;
   sd_cd_i                   : in    std_logic;
   sd2_reset_o               : out   std_logic;
   sd2_clk_o                 : out   std_logic;
   sd2_mosi_o                : out   std_logic;
   sd2_miso_i                : in    std_logic;
   sd2_cd_i                  : in    std_logic;
   csr_reset_o               : out   std_logic;
   csr_pause_o               : out   std_logic;
   csr_osm_o                 : out   std_logic;
   csr_keyboard_o            : out   std_logic;
   csr_joy1_o                : out   std_logic;
   csr_joy2_o                : out   std_logic;
   osm_xy_o                  : out   std_logic_vector(15 downto 0);
   osm_dxdy_o                : out   std_logic_vector(15 downto 0);
   ascal_mode_i              : in    std_logic_vector(4 downto 0);
   ascal_mode_o              : out   std_logic_vector(4 downto 0);
   keys_n_i                  : in    std_logic_vector(15 downto 0);
   control_d_o               : out   std_logic_vector(255 downto 0);
   control_m_o               : out   std_logic_vector(255 downto 0);
   special_i                 : in    std_logic_vector(15 downto 0);
   general_i                 : in    std_logic_vector(15 downto 0);
   ramrom_dev_o              : out   std_logic_vector(15 downto 0);
   ramrom_addr_o             : out   std_logic_vector(27 downto 0);
   ramrom_data_o             : out   std_logic_vector(15 downto 0);
   ramrom_data_i             : in    std_logic_vector(15 downto 0);
   ramrom_ce_o               : out   std_logic;
   ramrom_wait_i             : in    std_logic;
   ramrom_we_o               : out   std_logic
);
end entity qnice_host_stub;

architecture stub of qnice_host_stub is
   constant N : natural := 617;
   signal chain : std_logic_vector(N - 1 downto 0) := (others => '0');
   signal fold  : std_logic := '0';
   function xr(v : std_logic_vector) return std_logic is
      variable r : std_logic := '0';
   begin
      for i in v'range loop r := r xor v(i); end loop;
      return r;
   end function;
begin
   p_chain : process (clk50_i)
   begin
      if rising_edge(clk50_i) then
         fold  <= xr(std_logic_vector(ascal_mode_i)) xor
                  xr(std_logic_vector(ramrom_data_i)) xor
                  ramrom_wait_i;
         chain <= chain(N - 2 downto 0) & (uart_rxd_i xor fold xor reset_n_i);
      end if;
   end process p_chain;

   csr_reset_o <= chain(0);
   csr_pause_o <= chain(1);
   csr_osm_o <= chain(2);
   csr_keyboard_o <= chain(3);
   csr_joy1_o <= chain(4);
   csr_joy2_o <= chain(5);
   osm_xy_o <= chain(21 downto 6);
   osm_dxdy_o <= chain(37 downto 22);
   ascal_mode_o <= chain(42 downto 38);
   control_d_o <= chain(298 downto 43);
   control_m_o <= chain(554 downto 299);
   ramrom_dev_o <= chain(570 downto 555);
   ramrom_addr_o <= chain(598 downto 571);
   ramrom_data_o <= chain(614 downto 599);
   ramrom_ce_o <= chain(615);
   ramrom_we_o <= chain(616);
   sd_reset_o <= '1';   -- idle: the card path is not used by the host build
   sd_clk_o <= '0';   -- idle: the card path is not used by the host build
   sd_mosi_o <= '0';   -- idle: the card path is not used by the host build
   sd2_reset_o <= '1';   -- idle: the card path is not used by the host build
   sd2_clk_o <= '0';   -- idle: the card path is not used by the host build
   sd2_mosi_o <= '0';   -- idle: the card path is not used by the host build
   uart_txd_o <= '1';   -- idle: the card path is not used by the host build
end architecture stub;
